const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');
const { db } = require('../db');
const { auditLogs } = require('../schema');
const { eq } = require('drizzle-orm');

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key", "@external"])

  extend type User @key(fields: "id") {
    id: ID! @external
    securityAuditLogs: [AuditLog!]!
  }

  type AuditLog {
    id: ID!
    ipAddress: String!
    action: String!
    timestamp: String!
  }
`;

const resolvers = {
  User: {
    securityAuditLogs: async (parent, args, context) => {
      if (!context.user) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }
      const isSelf = context.user.id === parent.id;
      const isAuditAdmin = context.user.roles?.includes('SECURITY_AUDITOR');
      if (!isSelf && !isAuditAdmin) {
        throw new GraphQLError('Forbidden: insufficient permissions to view audit logs', { extensions: { code: 'FORBIDDEN' } });
      }
      return await db.select()
        .from(auditLogs)
        .where(eq(auditLogs.userId, parent.id));
    },
  },
};
